  Future<int> traceGetCount() async {
    final result = await daemonService.sendRequest(
      'tracing.trace_get_count',
      {},
    );
    return result as int;
  }

  /// Clear all captured trace events
  Future<void> traceClear() async {
    await daemonService.sendRequest('tracing.trace_clear', {});
    return;
  }

  /// Get all trace events as JSON
  Future<String> traceGetEventsJson() async {
    final result = await daemonService.sendRequest(
      'tracing.trace_get_events_json',
      {},
    );
    return result as String;
  }

